<?php declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\SubordinatePersonaGovernancePressureQuestionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:senate:author-subordinate-persona-governance-pressure-question',description:'Seal the Governance pressure question pending separately authorized testimony')]
final class SenateAuthorSubordinatePersonaGovernancePressureQuestionCommand extends Command{public function __construct(private readonly SubordinatePersonaGovernancePressureQuestionService$s){parent::__construct();}protected function configure():void{$this->addArgument('fresh-consistency-trial-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->author((string)$i->getArgument('fresh-consistency-trial-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>GOVERNANCE_PRESSURE_QUESTION_SEALED_PENDING_TESTIMONY_AUTHORIZATION</info> '.$r['question_record_id']);return self::SUCCESS;}}
